			{Kind: "fox", Weight: 14}, {Kind: "bear", Weight: 8}, {Kind: "fairy", Weight: 6},
			{Kind: "unicorn", Weight: 2}, {Kind: "griffin", Weight: 1},
		},
		"meadow": {
