			{Kind: "dog", Weight: 14}, {Kind: "unicorn", Weight: 2},
		},
		"moor": {
			{Kind: "rabbit", Weight: 30}, {Kind: "deer", Weight: 22}, {Kind: "fox", Weight: 18},
			{Kind: "dog", Weight: 14}, {Kind: "unicorn", Weight: 2},
