)

func SetHouseSign(cur realm, playerName string, buildingID uint64, text string) string {
	key, player := ownedPlayer(cur, playerName)
	b := buildings[buildingID]
	if b == nil {
		panic("house not found")
	}
	if normalizeKey(b.OwnerPlayer) != key {
		panic("only the house owner may set the sign")
	}
	if !types.SameTile(player.Pos, b.Pos) {
		panic("you must be at the house to set its sign")
	}
	text = cleanName(text)
	if len(text) > 120 {
		panic("sign text must be 120 characters or fewer")
	}
	b.Sign = text
	label := text
	if label == "" {
		label = "(cleared)"
	}
	createDiary(key, "sign", "house_sign", "House #"+strconv.Itoa(int(buildingID))+"\nSign:"+label)
	if text == "" {
		return "sign cleared on house #" + strconv.Itoa(int(buildingID))
	}
	return "sign set on house #" + strconv.Itoa(int(buildingID))
}

func DescribeTileBuildings(x uint64, y uint64) string {
	if !book.InBounds(x, y) {
		panic("tile out of bounds")
	}
	pos := types.Position{X: x, Y: y}
	ids := tileHouses[tileKey(pos)]
	out := "Tile (" + strconv.Itoa(int(x)) + "," + strconv.Itoa(int(y)) + ")\n"
	out += "Houses: " + strconv.Itoa(int(len(ids))) + "\n"
	out += "NextBuildCost: " + strconv.Itoa(int(rules.HouseBuildCost(uint64(len(ids))))) + " pearls\n"
	if len(ids) == 0 {
		out += "No houses here."
		return out
	}
	for _, id := range ids {
		b := buildings[id]
		if b == nil {
			continue
		}
		out += "- #" + strconv.Itoa(int(b.ID)) + " owner:" + b.OwnerPlayer
		if b.Sign != "" {
			out += " sign:\"" + b.Sign + "\""
		} else {
			out += " sign:(none)"
		}
		out += "\n"
	}
	return out
}

func ListPlayerHouses(playerName string) string {
	key := normalizeKey(playerName)
	player, ok := players[key]
	if !ok {
		panic("player not found")
	}
	out := "Houses owned by " + player.Name + "\n"
	count := 0
	for id := uint64(1); id < nextBuildingID; id++ {
		b := buildings[id]
		if b == nil || normalizeKey(b.OwnerPlayer) != key {
			continue
		}
		count++
		out += "- #" + strconv.Itoa(int(b.ID)) +
			" @ (" + strconv.Itoa(int(b.Pos.X)) + "," + strconv.Itoa(int(b.Pos.Y)) + ")"
		if b.Sign != "" {
			out += " \"" + b.Sign + "\""
		}
		out += "\n"
	}
	if count == 0 {
		out += "None."
	}
	return out
}

func DescribeTileSceneAt(x uint64, y uint64) string {
	if !book.InBounds(x, y) {
		panic("tile out of bounds")
	}
	pos := types.Position{X: x, Y: y}
	code := book.Tile(x, y)
	tk := tileKey(pos)
	named := namedPlaces[tk] != ""
	out := "TileSceneID: tile-" + strconv.Itoa(int(x)) + "-" + strconv.Itoa(int(y)) + "\n"
	out += "TileScenePlaceName: " + placeName(pos) + "\n"
	out += "TileSceneTerrain: " + book.TerrainName(code) + "\n"
	out += "TileSceneResources: " + book.TerrainResources(code) + "\n"
	if book.PlaceCanBeNamed(code, named) {
		out += "TileSceneCanName: yes\n"
	} else {
		out += "TileSceneCanName: no\n"
	}
	ids := tileHouses[tk]
	out += "TileSceneHouses: " + strconv.Itoa(int(len(ids))) + "\n"
	out += "TileSceneNextBuildCost: " + strconv.Itoa(int(rules.HouseBuildCost(uint64(len(ids))))) + "\n"
	for _, id := range ids {
		b := buildings[id]
		if b == nil {
			continue
		}
		out += "House #" + strconv.Itoa(int(b.ID)) + " owner:" + b.OwnerPlayer
		if b.Sign != "" {
			out += " sign:\"" + b.Sign + "\""
		}
		out += "\n"
	}
	return out
}

package nisse2

import "strconv"

type Message struct {
	ID   uint64
	From string
	To   string
	Body string
	Turn uint64
}

var messages map[string]map[uint64]*Message
var nextMessageID uint64

func init() {
	messages = make(map[string]map[uint64]*Message)
	nextMessageID = 1
}

func pairSeed(from string, to string) uint64 {
	source := normalizeKey(from) + "::" + normalizeKey(to)
	sum := uint64(0)
	for i := 0; i < len(source); i++ {
		sum += uint64(source[i]) * uint64(i+1)
	}
	return sum%251 + 1
}

func hexDigit(n uint8) byte {
	if n < 10 {
		return byte('0' + n)
	}
	return byte('a' + (n - 10))
}

func encodeMessage(from string, to string, body string) string {
	seed := pairSeed(from, to)
	out := ""
	for i := 0; i < len(body); i++ {
		mask := uint8((seed + uint64(i*17)) % 256)
		encoded := uint8(body[i]) ^ mask
		out += string([]byte{hexDigit(encoded >> 4), hexDigit(encoded & 15)})
	}
	return out
}

func WriteToFriend(cur realm, fromPlayerName string, toPlayerName string, body string) string {
	fromKey, fromPlayer := ownedPlayer(cur, fromPlayerName)
	_ = fromKey
	toPlayerName = cleanName(toPlayerName)
	body = cleanName(body)
	if toPlayerName == "" {
		panic("recipient required")
	}
	if body == "" {
		panic("message body is required")
	}
	toKey := normalizeKey(toPlayerName)
	toPlayer, ok := players[toKey]
	if !ok {
		panic("recipient not found")
	}
	if messages[toKey] == nil {
		messages[toKey] = make(map[uint64]*Message)
	}
	id := nextMessageID
	nextMessageID++
	messages[toKey][id] = &Message{
		ID:   id,
		From: fromPlayer.Name,
		To:   toPlayer.Name,
		Body: encodeMessage(fromPlayer.Name, toPlayer.Name, body),
		Turn: fromPlayer.Turns,
	}
	return "message sent"
}

func GetMessages(playerName string) string {
	key := normalizeKey(playerName)
	entryMap, ok := messages[key]
	if !ok || len(entryMap) == 0 {
		return "No messages."
	}
	out := "Messages for " + playerName + "\n"
	for id := uint64(1); id < nextMessageID; id++ {
		entry, exists := entryMap[id]
		if !exists {
			continue
		}
		out += "- #" + strconv.Itoa(int(entry.ID)) + " from " + entry.From + ": " + entry.Body + "\n"
	}
	return out
}

func DescribeLatestIncomingMessage(playerName string) string {
	key := normalizeKey(playerName)
	entryMap, ok := messages[key]
	if !ok || len(entryMap) == 0 {
		return "No messages."
	}
	var latest *Message
	for id := uint64(1); id < nextMessageID; id++ {
		entry, exists := entryMap[id]
		if !exists {
			continue
		}
		latest = entry
	}
	if latest == nil {
		return "No messages."
	}
	out := "Latest message for " + playerName + "\n"
	out += "From: " + latest.From + "\n"
	out += "Turn: " + strconv.Itoa(int(latest.Turn)) + "\n"
	out += "Body: " + latest.Body
	return out
}

